syntax = "proto3";

package hasher.v1;

option go_package = "knirvhasher/proto/hasher/v1;hasherv1";

// hasherService provides ASIC computation services
service hasherService {
  // ComputeHash computes a single SHA-256 hash
  rpc ComputeHash(ComputeHashRequest) returns (ComputeHashResponse);

  // ComputeBatch computes multiple SHA-256 hashes in a batch
  rpc ComputeBatch(ComputeBatchRequest) returns (ComputeBatchResponse);

  // StreamCompute streams hash computations for high-throughput scenarios
  rpc StreamCompute(stream StreamComputeRequest) returns (stream StreamComputeResponse);

  // GetMetrics retrieves performance metrics from eBPF
  rpc GetMetrics(GetMetricsRequest) returns (GetMetricsResponse);

  // GetDeviceInfo retrieves ASIC device information
  rpc GetDeviceInfo(GetDeviceInfoRequest) returns (GetDeviceInfoResponse);

  // MineWork performs mining on a Bitcoin-style header to find a valid nonce
  rpc MineWork(MineWorkRequest) returns (MineWorkResponse);

  // VerifyMath verifies a mathematical derivation step
  rpc VerifyMath(VerifyMathRequest) returns (VerifyMathResponse);
}

// HasherTrainingService provides dataset collection and training pipeline services
service HasherTrainingService {
  // ExportSecurityData streams DVE data to the hasher for dataset collection
  rpc ExportSecurityData(ExportRequest) returns (stream EncryptedChunk);

  // TriggerTraining triggers a training job on the hasher
  rpc TriggerTraining(TrainingRequest) returns (TrainingResponse);

  // GetTrainingStatus retrieves the status of a training job
  rpc GetTrainingStatus(TrainingStatusRequest) returns (TrainingStatusResponse);

  // GetUserRules retrieves trained security rules for a user
  rpc GetUserRules(RulesRequest) returns (RulesResponse);

  // ValidateAction validates an action against trained user rules
  rpc ValidateAction(ActionRequest) returns (ActionResponse);
}

// ComputeHashRequest contains data for single hash computation
message ComputeHashRequest {
  // Data to hash (arbitrary bytes)
  bytes data = 1;
}

// ComputeHashResponse contains the computed hash and latency info
message ComputeHashResponse {
  // Computed SHA-256 hash (32 bytes)
  bytes hash = 1;

  // Operation latency in microseconds
  uint64 latency_us = 2;
}

// ComputeBatchRequest contains multiple data items to hash
message ComputeBatchRequest {
  // Array of data items to hash
  repeated bytes data = 1;

  // Maximum batch size (optional, defaults to 256)
  // Server will process in optimal hardware batches
  uint32 max_batch_size = 2;
}

// ComputeBatchResponse contains all computed hashes
message ComputeBatchResponse {
  // Array of computed hashes (same order as input)
  repeated bytes hashes = 1;

  // Total operation latency in microseconds
  uint64 total_latency_us = 2;

  // Number of hashes successfully processed
  uint32 processed_count = 3;
}

// StreamComputeRequest is sent by client in streaming mode
message StreamComputeRequest {
  // Data to hash
  bytes data = 1;

  // Client-provided request ID for correlation
  uint64 request_id = 2;
}

// StreamComputeResponse is returned by server in streaming mode
message StreamComputeResponse {
  // Computed hash
  bytes hash = 1;

  // Request ID from the original request
  uint64 request_id = 2;

  // Operation latency in microseconds
  uint64 latency_us = 3;
}

// GetMetricsRequest requests performance metrics
message GetMetricsRequest {
  // Reserved for future use (e.g., time range filters)
}

// GetMetricsResponse contains aggregated performance metrics
message GetMetricsResponse {
  // Total number of hash requests processed
  uint64 total_requests = 1;

  // Total bytes processed across all requests
  uint64 total_bytes_processed = 2;

  // Average latency in microseconds
  uint64 average_latency_us = 3;

  // Peak latency in microseconds
  uint64 peak_latency_us = 4;

  // Total number of errors encountered
  uint64 total_errors = 5;

  // Cache hit count (reserved for future use)
  uint64 cache_hits = 6;

  // Cache miss count (reserved for future use)
  uint64 cache_misses = 7;

  // Device-specific statistics
  map<string, uint64> device_stats = 8;
}

// GetDeviceInfoRequest requests device information
message GetDeviceInfoRequest {
  // Empty for now
}

// GetDeviceInfoResponse contains ASIC device information
message GetDeviceInfoResponse {
  // Device file path (e.g., /dev/bitmain-asic)
  string device_path = 1;

  // Number of chips in the ASIC
  uint32 chip_count = 2;

  // Firmware version string
  string firmware_version = 3;

  // Whether device is operational
  bool is_operational = 4;

  // Server uptime in seconds
  uint64 uptime_seconds = 5;
}

// MineWorkRequest contains data for mining a nonce
message MineWorkRequest {
  // 80-byte Bitcoin-style block header
  bytes header = 1;

  // Starting nonce value for search
  uint32 nonce_start = 2;

  // Ending nonce value for search
  uint32 nonce_end = 3;
}

// MineWorkResponse contains the found nonce
message MineWorkResponse {
  // The first valid nonce found
  uint32 nonce = 1;

  // Operation latency in microseconds
  uint64 latency_us = 2;
}

// VerifyMathRequest for math derivation verification
message VerifyMathRequest {
  // Context description of the derivation
  string context = 1;

  // The proposed mathematical step (LaTeX)
  string proposition = 2;

  // Math subdomain (e.g., 0x2200 for Calculus)
  uint32 subdomain = 3;

  // Confidence threshold (0.0-1.0)
  float confidence_threshold = 4;
}

// VerifyMathResponse for math verification result
message VerifyMathResponse {
  // Verification status
  string status = 1;

  // Golden nonce if verified
  string nonce = 2;

  // Result hash
  string result_hash = 3;

  // Detokenized output
  string detokenized_output = 4;

  // Logic integrity score (0.0-1.0)
  float logic_integrity = 5;

  // Latency in milliseconds
  float latency_ms = 6;
}

// ExportRequest requests DVE data export from KNIRVSERVER
message ExportRequest {
  // Organization ID
  string org_id = 1;

  // User ID
  string user_id = 2;

  // Type of data to export
  DataType data_type = 3;

  // Whether to encrypt the exported data
  bool encrypted = 4;
}

// DataType enumerates the types of data that can be exported
enum DataType {
  ALL = 0;
  ONTOLOGY = 1;
  GUARDRAILS = 2;
  ACTIVITY = 3;
  MARKDOWN = 4;
}

// EncryptedChunk is a chunk of encrypted data
message EncryptedChunk {
  // Encrypted data payload
  bytes data = 1;

  // Unique chunk identifier
  string chunk_id = 2;

  // Whether this is the last chunk
  bool is_last = 3;
}

// TrainingRequest triggers a training job
message TrainingRequest {
  // Organization ID
  string org_id = 1;

  // User ID
  string user_id = 2;

  // Training trigger type
  TrainingTrigger trigger = 3;

  // Additional options
  map<string, string> options = 4;
}

// TrainingTrigger enumerates training job triggers
enum TrainingTrigger {
  ON_DEMAND = 0;
  SCHEDULED = 1;
  GUARDRAIL_VIOLATION = 2;
}

// TrainingResponse is the response to a training request
message TrainingResponse {
  // Unique training job identifier
  string training_id = 1;

  // Current status of the training job
  string status = 2;
}

// TrainingStatusRequest requests the status of a training job
message TrainingStatusRequest {
  // Training job identifier
  string training_id = 1;
}

// TrainingStatusResponse contains training job status
message TrainingStatusResponse {
  // Training job identifier
  string training_id = 1;

  // Current status
  string status = 2;

  // Progress percentage (0-100)
  uint32 progress = 3;

  // Error message if failed
  string error = 4;
}

// RulesRequest requests trained security rules
message RulesRequest {
  // User ID
  string user_id = 1;

  // Organization ID
  string org_id = 2;
}

// RulesResponse contains trained security rules
message RulesResponse {
  // Array of trained rule identifiers
  repeated string rule_ids = 1;

  // Rule data as JSON
  string rules_json = 2;
}

// ActionRequest requests action validation
message ActionRequest {
  // User ID
  string user_id = 1;

  // Action to validate
  string action = 2;

  // Additional context
  map<string, string> context = 3;
}

// ActionResponse is the response to an action validation request
message ActionResponse {
  // Whether the action is allowed
  bool allowed = 1;

  // Confidence score (0.0-1.0)
  float confidence = 2;

  // Rule violations detected
  repeated string violations = 3;

  // Rules that were applied
  repeated string applied_rules = 4;
}

package trainer

import (
	"bytes"
	"crypto/sha256"
	"encoding/gob"
	"fmt"
	"math"
	"strings"

	"github.com/lab/hasher/data-trainer/internal/config"
)

// Trainer implements curriculum-based training with stage-gated data selection.
type Trainer struct {
	config       *config.CurriculumConfig
	currentStage config.CurriculumStage
	epoch        int
	loss         float64
	dataSelector func(stage config.CurriculumStage, data []TrainingSample) []TrainingSample
}

// TrainingSample represents a single training data point.
type TrainingSample struct {
	ID    string
	Input []float64
	Label float64
	Difficulty float64 // Used for curriculum gating
}

// NewTrainer creates a new curriculum trainer with the given config.
func NewTrainer(cfg *config.CurriculumConfig) *Trainer {
	if cfg == nil {
		cfg = &config.CurriculumConfig{
			Stage:          config.CurriculumApprentice,
			LearningRate:   0.01,
			AdvanceTrigger: "loss<0.5",
			MaxEpochs:      100,
		}
	}
	return &Trainer{
		config:       cfg,
		currentStage: cfg.Stage,
		epoch:        0,
		loss:         math.Inf(1),
		dataSelector: defaultDataSelector,
	}
}

// SetDataSelector sets a custom function for stage-gated data selection.
func (t *Trainer) SetDataSelector(selector func(stage config.CurriculumStage, data []TrainingSample) []TrainingSample) {
	t.dataSelector = selector
}

// TrainEpoch runs one epoch of curriculum-gated training.
// Returns the loss for this epoch and whether the stage should advance.
func (t *Trainer) TrainEpoch(data []TrainingSample) (float64, bool, error) {
	t.epoch++

	// Stage-gated data selection: filter data based on current stage
	selected := t.dataSelector(t.currentStage, data)
	if len(selected) == 0 {
		return 0, false, fmt.Errorf("no training data available for stage %s", t.currentStage)
	}

	// Simulate training: compute average loss on selected data
	// In production, this would actually run the model forward/backward pass
	loss := t.simulateTraining(selected)
	t.loss = loss

	// Check if we should advance to next stage
	shouldAdvance := t.shouldAdvanceStage(loss)

	return loss, shouldAdvance, nil
}

// shouldAdvanceStage checks if the advance trigger condition is met.
func (t *Trainer) shouldAdvanceStage(loss float64) bool {
	trigger := t.config.AdvanceTrigger
	if trigger == "" {
		return false
	}

	// Parse simple trigger conditions like "loss<0.5" or "epoch>10"
	// For now, support "loss<X" format
	if strings.HasPrefix(trigger, "loss<") {
		var threshold float64
		_, err := fmt.Sscanf(trigger, "loss<%f", &threshold)
		if err == nil && loss < threshold {
			return true
		}
	}
	return false
}

// AdvanceStage moves to the next curriculum stage.
// Returns the new stage and false if already at the highest stage.
func (t *Trainer) AdvanceStage() (config.CurriculumStage, bool) {
	switch t.currentStage {
	case config.CurriculumApprentice:
		t.currentStage = config.CurriculumJourneyman
		t.config.Stage = t.currentStage
		return t.currentStage, true
	case config.CurriculumJourneyman:
		t.currentStage = config.CurriculumExpert
		t.config.Stage = t.currentStage
		return t.currentStage, true
	case config.CurriculumExpert:
		return t.currentStage, false // Already at highest stage
	default:
		return t.currentStage, false
	}
}

// GetCurrentStage returns the current curriculum stage.
func (t *Trainer) GetCurrentStage() config.CurriculumStage {
	return t.currentStage
}

// GetEpoch returns the current epoch number.
func (t *Trainer) GetEpoch() int {
	return t.epoch
}

// GetLoss returns the current loss.
func (t *Trainer) GetLoss() float64 {
	return t.loss
}

// defaultDataSelector implements stage-gated data selection.
// - Apprentice: uses easy samples (low difficulty)
// - Journeyman: uses medium+ difficulty samples
// - Expert: uses all samples
func defaultDataSelector(stage config.CurriculumStage, data []TrainingSample) []TrainingSample {
	var filtered []TrainingSample
	for _, sample := range data {
		switch stage {
		case config.CurriculumApprentice:
			if sample.Difficulty <= 0.3 {
				filtered = append(filtered, sample)
			}
		case config.CurriculumJourneyman:
			if sample.Difficulty <= 0.7 {
				filtered = append(filtered, sample)
			}
		case config.CurriculumExpert:
			filtered = append(filtered, sample) // All data
		default:
			filtered = append(filtered, sample)
		}
	}
	return filtered
}

// simulateTraining simulates one training epoch.
// In production, this would integrate with the actual model.
func (t *Trainer) simulateTraining(data []TrainingSample) float64 {
	if len(data) == 0 {
		return 0
	}
	// Simple simulation: loss decreases with more data and easier samples
	// and as we progress through epochs
	baseLoss := 1.0
	difficultySum := 0.0
	for _, d := range data {
		difficultySum += d.Difficulty
	}
	avgDifficulty := difficultySum / float64(len(data))

	// Loss decreases with more epochs and easier data
	epochFactor := math.Exp(-float64(t.epoch) * 0.01)
	difficultyFactor := 1.0 - avgDifficulty*0.5

	loss := baseLoss * epochFactor * difficultyFactor
	if loss < 0.01 {
		loss = 0.01 // Minimum loss
	}
	return loss
}

// HashNetwork provides hashing utilities for the trainer.
type HashNetwork struct{}

// SHA256Hash computes the SHA256 hash of various input types.
func SHA256Hash(input interface{}) [32]byte {
	var data []byte
	switch v := input.(type) {
	case string:
		data = []byte(v)
	case []float64:
		var buf bytes.Buffer
		enc := gob.NewEncoder(&buf)
		enc.Encode(v)
		data = buf.Bytes()
	case []byte:
		data = v
	default:
		data = []byte{}
	}
	return sha256.Sum256(data)
}

package training

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"math"
	"math/bits"
	mathrand "math/rand"
	"sort"
	"time"

	"knirvhasher/pkg/hashing/core"
	"knirvhasher/pkg/hashing/hardware"
	"knirvhasher/pkg/hashing/methods/cuda"

	"github.com/lab/hasher/data-trainer/internal/config"
	"github.com/lab/hasher/data-trainer/pkg/simulator"
)

const (
	SeedSize          = 32
	FeatureVectorSize = 12
	GroupSize         = 128
	MutationRateBase  = 10
